import {ITEMS,FIELD_RECIPES,ENERGY,mass,fabricate} from './survival.js';
import {glyph} from './item-icons.js';

const groups={material:['Materials','#d9b77b'],tool:['Tools','#86c8d3'],component:['Components','#c9ade5'],equipment:['Equipment','#a9cab0'],energy:['Energy','#e5ce7a'],junk:['Salvage','#b6aca0']};
const itemArt={wire:['Cable','WIRE'],cells:['BatteryMedium','CELL'],electronics:['CircuitBoard','PCB'],steel:['Anvil','FE'],copper:['Orbit','CU'],aluminum:['Layers2','AL'],plastic:['Package','POLY'],glass:['Gem','GLS'],rubber:['CircleDashed','RUB'],fabric:['Shirt','TEX'],magnets:['Magnet','MAG'],bearings:['CircleDot','BRG'],silicon:['Cpu','SI'],screwdriver:['PenTool','DRV'],pickaxe:['Pickaxe','PICK'],wrench:['Wrench','HEX'],cutters:['Scissors','CUT'],toaster:['Microwave','HTR'],laptop:['Laptop','PC'],motor:['Cog','MTR'],panel:['SolarPanel','PV'],bottle:['BottleWine','BTL'],rag:['BrushCleaning','RAG'],can:['Cylinder','CAN'],wrapper:['Receipt','PKG'],tire:['Disc','TIRE'],fuel:['Fuel','FUEL'],fuse:['PlugZap','FUSE'],radioCoil:['Radio','COIL'],signalFilter:['RadioReceiver','147'],fieldCell:['BatteryCharging','PWR'],patchKit:['Bandage','FIX']};
const descriptions={wire:'Insulated conductors for circuit repairs, drone modules and battery assemblies.',cells:'Individual lithium cells. Recondition them into bike charge or build a sealed reserve cell.',electronics:'Recovered circuit boards, connectors and control parts for repairs and fabrication.',steel:'Structural scrap for tools, motor upgrades and hull repairs.',copper:'Conductive metal. Strip it into wire, wind coils or rebuild electrical parts.',aluminum:'Lightweight metal recovered from panels and discarded containers.',plastic:'Insulation and housings. Combine with copper to make wire and radio coils.',glass:'Recovered glass for protected replacement fuses.',rubber:'Grip and insulation material for tools, reserve cells and repair kits.',fabric:'Recovered cloth for field repair kits.',magnets:'Permanent magnets recovered from electric motors.',bearings:'Rolling hardware recovered from motor assemblies.',silicon:'Recovered solar-cell material.',screwdriver:'Opens household appliances and electrical equipment. Keep it in your pack for salvage and fabrication.',pickaxe:'Extracts steel and copper from marked deposits. Work near a deposit for four seconds.',wrench:'Dismantles seized motors and assembles heavy tools and repair kits.',cutters:'Cuts tires into rubber and strips copper into insulated wire.',toaster:'A broken heating appliance. Open it to recover useful metal and wiring.',laptop:'A dead portable computer with recoverable circuitry and battery cells.',motor:'A heavy, seized electric motor. Its windings, magnets and bearings are still useful.',panel:'A damaged photovoltaic panel with recoverable frame, glass and silicon.',bottle:'An empty glass container. Break it down for glass.',rag:'Oil-stained cloth. Recover the usable fabric.',can:'A crushed drinks can. Recover a small amount of aluminum.',wrapper:'Discarded packaging. Recover a small amount of plastic.',tire:'A ruined tire. Cut away three units of reusable rubber.',fuel:'One liter of generator fuel. Pour it into the nearby trailer; its tank holds five liters.',fieldCell:'A sealed reserve assembly. Consume one to recover 12 percentage points of bike charge.',patchKit:'A field repair kit. Consume one to restore up to 25 hull points.'};
const escape=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const packViews={inventory:{source:'pack',category:'all',query:'',sort:'category',selected:''},supplies:{source:'pack',category:'all',query:'',sort:'category',selected:''}};
let activeView='inventory',tooltip=null,tooltipAnchor=null,suppressTip=false;
export function itemSymbol(id,extra=''){const d=ITEMS[id],art=itemArt[id]||['Package',id.toUpperCase()];return `<span class="itemSymbol ${extra}" style="--item-accent:${groups[d?.category]?.[1]||'#9cbab4'}">${glyph(art[0])}<small>${art[1]}</small></span>`;}
export function itemDescription(id){return descriptions[id]||ITEMS[id]?.description||'';}
export function hideItemTooltip(){if(tooltip)tooltip.hidden=true;tooltipAnchor?.removeAttribute('aria-describedby');tooltipAnchor=null;}
function sourceInventory(o,v){if(v.source==='found')return o.nearby?.items||{};return v.source==='pack'?o.state.inv:o.state.field.storage[v.source]||{};}
function itemMatches(id,v){const d=ITEMS[id];return (v.category==='all'||d.category===v.category)&&(!v.query||`${d.name} ${d.category} ${itemDescription(id)}`.toLowerCase().includes(v.query.toLowerCase()));}
function recipeUses(id){return Object.values(FIELD_RECIPES).filter(r=>r.inputs[id]||r.tool===id).map(r=>r.name);}
function ingredientList(items,inv){return Object.entries(items).map(([id,q])=>`<span class="ingredient ${inv&&(inv[id]||0)<q?'is-missing':''}">${itemSymbol(id)}<span>${escape(ITEMS[id].name)} <b>${inv?`${Math.min(inv[id]||0,q)} / `:''}${q}</b></span></span>`).join('');}
function itemActions(id,q,o,v){const d=ITEMS[id],s=o.state,locked=!o.started||s.dead||s.mode==='drone';let html='';
 const btn=(text,attrs,disabled=false)=>`<button ${attrs} ${disabled||locked?'disabled':''}>${text}</button>`;
 if(v.source==='found')return btn('Take one',`data-field="loot" data-item="${id}"`,!o.nearby||q<1);
 if(v.source!=='pack')return btn('Move one to backpack',`data-field="retrieve" data-item="${id}" data-storage="${v.source}"`,!o.nearStorage(v.source))+(!o.nearStorage(v.source)?'<p class="pack-note">Move within 8 m of this vehicle.</p>':'');
 if(['tool','component','equipment'].includes(d.category))html+=btn(s.relayHouse.selected===id?'Equipped · return to world':'Equip for use',`data-use-item="${id}"`);
 if(d.salvage)html+=btn('Salvage one',`data-field="salvage" data-item="${id}"`,!!d.tool&&!s.inv[d.tool]);
 if(id==='fieldCell'||id==='patchKit')html+=btn(id==='fieldCell'?'Use · +12 bike charge':'Use · +25 hull',`data-field="consume" data-item="${id}"`,id==='fieldCell'?s.battery>=88:s.hp>=100);
 if(id==='fuel')html+=btn('Pour 1 L into generator','data-field="refuel"',!o.nearStorage('trailer')||s.fuel>4);
 html+=`<div class="pack-transfer">${['bike','trailer'].map(k=>btn(`Store one · ${k}`,`data-field="store" data-item="${id}" data-storage="${k}"`,!o.nearStorage(k))).join('')}</div>`;
 html+=btn('Discard one',`data-drop="${id}" class="pack-discard"`,d.essential&&!s.relayHouse.discovered);
 if(d.essential&&!s.relayHouse.discovered)html+='<p class="pack-note">Protected mission part · vehicle storage is available.</p>';
 if(locked)html+='<p class="pack-note">Return to a living rider to handle supplies.</p>';
 return html;
}
function inspector(id,inv,o,v){if(!id)return '<aside class="pack-inspector"><p>Select an item to inspect its uses and actions.</p></aside>';const d=ITEMS[id],q=inv[id],uses=recipeUses(id);
 return `<aside class="pack-inspector" id="packInspector" aria-label="Selected item"><div class="inspector-art">${itemSymbol(id,'large')}<span>${groups[d.category][0]}${d.essential?' · mission part':''}</span></div><h3>${escape(d.name)}</h3><p>${escape(itemDescription(id))}</p><dl class="item-facts"><div><dt>Carrying</dt><dd>${q} <small>units</small></dd></div><div><dt>Total mass</dt><dd>${(d.mass*q).toFixed(2)} <small>kg</small></dd></div><div><dt>Each</dt><dd>${d.mass.toFixed(2)} <small>kg</small></dd></div><div><dt>Trade value</dt><dd>${d.value} <small>/ unit</small></dd></div></dl>${d.salvage?`<h4>Recovery per item</h4><div class="ingredient-list">${ingredientList(d.salvage)}</div><p class="pack-note">${d.tool?(o.state.inv[d.tool]?'Tool ready: ':'Required: ')+ITEMS[d.tool].name:'No tool required.'}</p>`:uses.length?`<details class="item-uses"><summary>Used in ${uses.length} recipes</summary><ul>${uses.map(t=>`<li>${escape(t)}</li>`).join('')}</ul></details>`:''}<div class="item-actions">${itemActions(id,q,o,v)}</div></aside>`;
}
export function renderBackpack(o,screen='inventory'){
 hideItemTooltip();activeView=screen;const v=packViews[screen],s=o.state;
 if(!['pack','bike','trailer','found'].includes(v.source)||v.source==='found'&&(!o.nearby||o.nearby.kind!=='container'))v.source='pack';
 const inv=sourceInventory(o,v),all=Object.keys(inv).filter(id=>ITEMS[id]&&inv[id]>0),ids=all.filter(id=>itemMatches(id,v));
 const categories=Object.keys(groups);ids.sort((a,b)=>(v.sort==='mass'?ITEMS[b].mass*inv[b]-ITEMS[a].mass*inv[a]:v.sort==='category'?categories.indexOf(ITEMS[a].category)-categories.indexOf(ITEMS[b].category):0)||ITEMS[a].name.localeCompare(ITEMS[b].name));
 if(!ids.includes(v.selected))v.selected=ids[0]||'';
 const cap=v.source==='pack'?o.capacity:v.source==='bike'?12:v.source==='trailer'?60:null,weight=mass(inv);
 const tile=id=>`<button class="pack-item ${v.selected===id?'is-selected':''}" data-pack-item="${id}" data-item-tip="${id}" aria-pressed="${v.selected===id}" aria-label="${escape(ITEMS[id].name)}, ${inv[id]} units, ${(ITEMS[id].mass*inv[id]).toFixed(2)} kilograms"><span class="pack-quantity">×${inv[id]}</span>${itemSymbol(id)}<b>${escape(ITEMS[id].name)}</b><span class="pack-item-mass">${(ITEMS[id].mass*inv[id]).toFixed(2)} kg${s.relayHouse.selected===id&&v.source==='pack'?' · EQUIPPED':''}</span></button>`;
 let list='';for(const id of ids){if(v.sort==='category'&&(!list||ITEMS[ids[ids.indexOf(id)-1]]?.category!==ITEMS[id].category))list+=`<h4 class="pack-group">${groups[ITEMS[id].category][0]}</h4>`;list+=tile(id);}
 const found=o.nearby,deposit=found?.kind==='node';
 return `<div class="pack-view"><div class="pack-heading"><div><span class="eyebrow">EQUIPMENT / PERSONAL CARGO</span><h2>${screen==='inventory'?'Backpack':'Cargo & recovery'}</h2></div><div class="pack-weight"><b>${weight.toFixed(1)} <small>${cap?'/ '+cap+' ':''}kg</small></b><span>${all.length} item types</span><i style="--load:${Math.min(100,weight/(cap||weight||1)*100)}%"></i></div></div><nav class="pack-sources" aria-label="Cargo location">${[['pack','Backpack','Backpack'],['bike','Bike','Container'],['trailer','Trailer','Container'],...(found?.kind==='container'?[['found','Nearby salvage','Package']]:[])].map(([id,label,g])=>`<button data-pack-source="${id}" aria-pressed="${v.source===id}">${glyph(g)}${label}<small>${id==='pack'?mass(s.inv).toFixed(1):id==='found'?mass(found.items).toFixed(1):mass(s.field.storage[id]).toFixed(1)} kg</small></button>`).join('')}</nav>${deposit?`<div class="nearby-deposit"><span>${glyph('Pickaxe')} ${ITEMS[found.resource].name} deposit · ${found.left} remaining</span><button data-field="mine" ${!found.left||!s.inv.pickaxe?'disabled':''}>Mine · 4 seconds</button></div>`:''}${v.source==='found'?'<button data-field="all" class="take-all">Take what fits</button>':''}<div class="pack-toolbar"><label class="pack-search">${glyph('Search')}<input data-pack-search type="search" aria-label="Search items" placeholder="Search your items…" value="${escape(v.query)}"></label><label class="pack-sort"><span>Sort</span><select data-pack-sort aria-label="Sort items"><option value="category" ${v.sort==='category'?'selected':''}>Category</option><option value="name" ${v.sort==='name'?'selected':''}>Name</option><option value="mass" ${v.sort==='mass'?'selected':''}>Heaviest</option></select></label></div><div class="pack-filters" role="group" aria-label="Item categories"><button data-pack-category="all" aria-pressed="${v.category==='all'}">All <small>${all.length}</small></button>${Object.entries(groups).map(([id,[label]])=>`<button data-pack-category="${id}" aria-pressed="${v.category===id}">${label} <small>${all.filter(k=>ITEMS[k].category===id).length}</small></button>`).join('')}</div><div class="pack-layout"><div class="pack-list"><div class="pack-grid">${list||'<p class="pack-empty">'+(all.length?'No items match. Clear the search or choose another category.':'No items here yet.')+'</p>'}</div><p class="pack-help">Hover for a quick look. Select an item for actions.</p></div>${inspector(v.selected,inv,o,v)}</div>${s.relayHouse.selected?`<button data-use-item="" class="empty-hands">Put away ${escape(ITEMS[s.relayHouse.selected].name)}</button>`:''}</div>`;
}
export function renderWorkshop(o){hideItemTooltip();const s=o.state;
 const context={atTrailer:o.nearStorage('trailer'),atWorkbench:o.atWorkbench,powered:s.relayHouse.power,battery:s.battery,known:s.relayHouse.evidence};
 return `<div class="workshop-view"><div class="pack-heading"><div><span class="eyebrow">EQUIPMENT / FABRICATION</span><h2>Workshop</h2></div><span class="station-badge">${context.atWorkbench&&context.powered?'POWERED WORKBENCH':context.atTrailer?'TRAILER STATION':'FIELD TOOLS'}</span></div><p class="workshop-intro">Use materials from your backpack. Station and tool requirements appear on each recipe.</p><div class="workshop-recipes">${Object.entries(FIELD_RECIPES).map(([id,r])=>{const result=fabricate({...s.inv},id,o.capacity,context),ready=!result.error&&o.started&&!s.dead&&s.mode!=='drone';return `<article class="craft-card"><div class="craft-title">${itemSymbol(Object.keys(r.output)[0])}<div><small>${r.station.toUpperCase()} · ${r.energy?(r.energy*ENERGY.unitKWh).toFixed(2)+' kWh':'HAND TOOLS'}</small><h3>${r.name}</h3></div></div><div class="ingredient-list">${ingredientList(r.inputs,s.inv)}</div><div class="craft-footer"><span>${ready?'Ready to fabricate':escape(result.error||'Return to your rider')}<small>${ITEMS[r.tool].name}</small></span><button data-field="craft" data-item="${id}" ${ready?'':'disabled'}>Craft</button></div></article>`;}).join('')}</div><details class="bike-upgrades" open><summary>Bike & drone upgrades</summary><div class="workshop-recipes">${o.recipes.map(r=>{const done=!!s[r.id],blocked=!o.canCraft(r)||done||r.id==='repair'&&s.hp>=100||r.id==='module'&&s.battery>78||!o.started||s.dead||s.mode==='drone';return `<article class="craft-card"><h3>${r.title}</h3><p>${r.desc.split(' · ').slice(1).join(' · ')}</p><div class="ingredient-list">${ingredientList(r.cost,s.inv)}</div><button data-craft="${r.id}" ${blocked?'disabled':''}>${done?'Fitted':blocked?'Unavailable':'Build upgrade'}</button></article>`;}).join('')}</div></details></div>`;
}
export function setupBackpack(panel,render){
 const rerender=(selector,selection)=>{const scroll=panel.querySelector('.field-content')?.scrollTop||0;suppressTip=true;render();const content=panel.querySelector('.field-content');if(content)content.scrollTop=scroll;const next=panel.querySelector(selector);next?.focus({preventScroll:true});if(selection!=null&&next?.setSelectionRange){try{next.setSelectionRange(selection,selection);}catch{}}suppressTip=false;};
 panel.addEventListener('click',e=>{hideItemTooltip();const b=e.target.closest('[data-pack-item],[data-pack-source],[data-pack-category]');if(!b)return;const v=packViews[activeView];if(b.dataset.packItem){v.selected=b.dataset.packItem;rerender(`[data-pack-item="${v.selected}"]`);if(window.matchMedia?.('(max-width: 850px)').matches)panel.querySelector('#packInspector')?.scrollIntoView?.({block:'nearest'});}else if(b.dataset.packSource){v.source=b.dataset.packSource;v.selected='';rerender(`[data-pack-source="${v.source}"]`);}else{v.category=b.dataset.packCategory;rerender(`[data-pack-category="${v.category}"]`);}});
 panel.addEventListener('input',e=>{if(!e.target.matches('[data-pack-search]'))return;packViews[activeView].query=e.target.value;rerender('[data-pack-search]',e.target.selectionStart);});
 panel.addEventListener('change',e=>{if(!e.target.matches('[data-pack-sort]'))return;packViews[activeView].sort=e.target.value;rerender('[data-pack-sort]');});
 const show=e=>{const a=e.target.closest('[data-item-tip]');if(!a||suppressTip||e.pointerType==='touch'||!window.matchMedia?.('(pointer:fine) and (min-width:851px)').matches)return;hideItemTooltip();const id=a.dataset.itemTip,d=ITEMS[id];if(!tooltip){tooltip=document.createElement('div');tooltip.id='itemTooltip';tooltip.className='item-tooltip';tooltip.setAttribute('role','tooltip');document.body.appendChild(tooltip);}tooltip.innerHTML=`${itemSymbol(id)}<div><b>${escape(d.name)}</b><span>${groups[d.category][0]} · ${d.mass.toFixed(2)} kg each</span><p>${escape(itemDescription(id))}</p><small>Select to manage this item</small></div>`;tooltip.hidden=false;tooltipAnchor=a;a.setAttribute('aria-describedby','itemTooltip');const r=a.getBoundingClientRect(),t=tooltip.getBoundingClientRect();tooltip.style.left=Math.max(12,Math.min(window.innerWidth-t.width-12,r.right+12))+'px';tooltip.style.top=Math.max(12,Math.min(window.innerHeight-t.height-12,r.top))+'px';};
 panel.addEventListener('pointerover',show);panel.addEventListener('focusin',show);panel.addEventListener('pointerout',e=>{if(!e.target.closest('[data-item-tip]')?.contains(e.relatedTarget))hideItemTooltip();});panel.addEventListener('focusout',hideItemTooltip);document.addEventListener('scroll',hideItemTooltip,true);window.addEventListener('resize',hideItemTooltip);
 window.addEventListener('keydown',e=>{if(e.key==='Escape'&&tooltip&&!tooltip.hidden){hideItemTooltip();e.preventDefault();e.stopImmediatePropagation();}},true);
}
